SELECT sm.sm_ship_mode_id, sm.sm_type, d.d_year, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_return_amount) / NULLIF(SUM(cr.cr_return_quantity),0) AS avg_return_amount_per_qty, SUM(cr.cr_net_loss) AS total_net_loss, PERCENT_RANK() OVER (PARTITION BY d.d_year ORDER BY SUM(cr.cr_net_loss) ASC) AS loss_percentile FROM catalog_returns cr JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk WHERE cr.cr_return_quantity > 0 GROUP BY sm.sm_ship_mode_id, sm.sm_type, d.d_year ORDER BY d.d_year, loss_percentile
